    AND s.batch_id = #{batchId}

ORDER BY s.id

SELECT id FROM label_sequence
WHERE deleted = 0 AND project_id = #{projectId} AND sequence_token = #{token}

    AND batch_id = #{batchId}

mapper.insert:
INSERT INTO label_ego_pose (
    pose_token, translation, rotation, timestamp_us, created_by, updated_by
) VALUES (#{token}, #{translation}, #{rotation}, #{timestampUs}, #{userId}, #{userId})

INSERT INTO label_sequence (
    project_id, batch_id, sequence_token, name, description, frame_count, created_by, updated_by
) VALUES (#{projectId}, #{batchId}, #{token}, #{name}, #{description}, #{frameCount}, #{userId}, #{userId})

INSERT INTO label_annotation_object (
    annotation_id, frame_id, object_key, object_type, class_id, geometry_json,
    attr_json, track_token, instance_id, visibility, created_by, updated_by
) VALUES (
    #{annotationId}, #{frameId}, #{objectKey}, #{type}, #{classId}, #{geometry},
    #{attrs}, #{trackToken}, #{instanceId}, #{visibility}, #{userId}, #{userId}
)

mapper.update:
UPDATE label_instance
SET last_frame_id = #{frameId}, annotation_count = annotation_count + 1
WHERE id = #{id}

mapper.insert:
INSERT INTO label_instance (
    project_id, instance_token, class_id, first_frame_id, last_frame_id,
    annotation_count, created_by, updated_by
) VALUES (
    #{projectId}, #{instanceToken}, #{classId}, #{firstFrameId}, #{lastFrameId},
    1, #{userId}, #{userId}
)

INSERT INTO label_sensor_data (
    frame_id, sensor_id, calibration_id, ego_pose_id, file_name, file_url,
    file_format, width, height, is_key_frame, meta_json, created_by, updated_by
) VALUES (
    #{frameId}, #{sensorId}, #{calibrationId}, #{egoPoseId}, #{fileName}, #{fileUrl},
    #{fileFormat}, #{width}, #{height}, #{isKeyFrame}, #{metaJson}, #{userId}, #{userId}
)

INSERT INTO label_precheck (
    sequence_id, frame_id, object_key, check_type, message, created_by, updated_by
) VALUES (#{sequenceId}, #{frameId}, #{objectKey}, #{checkType}, #{message}, #{userId}, #{userId})
